def solution(input_str):
    lines = input_str.strip().split('\n')
    h, m, k = map(int, lines[0].split())
    h1, m1 = map(int, lines[1].split())
    h2, m2 = map(int, lines[2].split())

    h_digits = len(str(h - 1))
    m_digits = len(str(m - 1))

    def format_num(num, digits):
        return str(num).zfill(digits)

    def count_digit_changes(before, after):
        count = 0
        for i in range(h_digits):
            if before[i] != after[i]:
                count += 1
        for i in range(m_digits):
            if before[i] != after[i]:
                count += 1
        return count

    def next_time(curr_h, curr_m, total_h, total_m):
        new_m = curr_m + 1
        if new_m >= total_m:
            new_m = 0
            new_h = curr_h + 1
            if new_h >= total_h:
                new_h = 0
        else:
            new_h = curr_h
        return new_h, new_m

    total_changes = 0
    curr_h, curr_m = h1, m1

    while True:
        next_h, next_m = next_time(curr_h, curr_m, h, m)

        if next_h == h2 and next_m == m2:
            break
        elif curr_h != h2 and curr_m != m2 and (next_h == h2 and next_m == m2):
            break

        curr_before = format_num(curr_h, h_digits) + ":" + format_num(curr_m, m_digits)
        curr_after = format_num(next_h, h_digits) + ":" + format_num(next_m, m_digits)

        if curr_before + ":" in curr_after:
            curr_h, curr_m = next_h, next_m
            continue

        changes = 0
        for i in range(h_digits):
            if curr_before[i] != curr_after[i]:
                changes += 1
        for i in range(m_digits):
            if curr_before[i + h_digits + 2] != curr_after[i + h_digits + 2]:
                changes += 1

        if changes >= k:
            total_changes += 1

        curr_h, curr_m = next_h, next_m

    return str(total_changes) + "\n"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    results = []
    for x in range(1, n + 1):
        # Use set for fast membership checking
        occupied = set()
        total_days = 0

        for l, r in offers:
            duration = r - l + 1
            if duration < x:
                continue

            # Check if all days [l, r] are free
            conflict = False
            for day in range(l, r + 1):
                if day in occupied:
                    conflict = True
                    break

            if not conflict:
                # Mark all days as occupied
                for day in range(l, r + 1):
                    occupied.add(day)
                total_days += duration

        results.append(total_days)

    return '\n'.join(map(str, results)) + '\n'

