@lru_cache(maxsize=None)
def quick_sum(n):
    """Calculate sum of digit sums from 1 to n"""
    if n < 0:
        return 0
    if n == 0:
        return 0

    def rec(n):
        if n == 0:
            return 0
        s = str(n)
        m = len(s)
        pre = int(s[:-1]) if m > 1 else 0

        res = 0

        # For each position, consider all values smaller than the prefix
        for digit in range(1, int(s[0]) + 1):
            # Digit d at current positions, followed by all combinations
            res += (pre * m if m > 1 else digit)
            res += digit_sum(digit-1) * (10**(m-1))
            if m > 1:
                res += quick_sum_pre(pre)

            # Full (m-1) digit numbers for each prefix
            res += digit_sum(digit-1) * (m-1)
            res += (digit * (m-1))
            if m > 1:
                res += digit_sum_pre(10**(m-2) - 1)

        # Current digit and everything after
        pre = int(s[:-1]) if m > 1 else 0
        first = int(s[0])

        res += digit_sum(first - 1) * 10**(m - 1)
        res += first * (m - 1) * 10**(m - 2)
        res += digit_sum_pre(10**(m - 1) - 1)

        # The prefix itself with its digit sum
        if m > 1:
            res += digit_sum(pre)
            res += quick_sum(pre - 1)

        return res

    return rec(n)

def digit_sum_pre(n):
    """Sum of digit sums from 1 to n (helper)"""
    if n <= 0:
        return 0
    return quick_sum(n)

def digit_sum(x):
    """Sum of digits of x"""
    result = 0
    while x > 0:
        result += x % 10
        x //= 10
    return result

def quick_sum_range(l, r):
    """Sum of f(x) from l to r"""
    if l > r:
        return 0
    return quick_sum(r) - quick_sum(l - 1)

