            c = c1 + (r - r1) * (dc // dr) if dr != 0 else c1
            if (r, c) in grid and grid[(r, c)] in chocolates:
                line_choc.add(grid[(r, c)])
        return line_choc

    def get_winning_moves(choc_set):
        """Get all possible moves (sets of chocolates to remove)."""
        moves = set()

        for p1 in choc_set:
            for p2 in choc_set:
                line = get_lines_in_direction(choc_set, p1, p2)
                if len(line) >= 1:
                    for k in range(1, len(line) + 1):
