MOD = 1000000007

def solution(s):
    lines = s.strip().split('\n')
    if len(lines) < 2:
        return '0'

    n = int(lines[0])
    nums = list(map(int, lines[1].split()))

    # Find empty positions (where nums[i] == -1)
    empty_positions = []
    seen_values = set()

    for i in range(n):
        val = nums[i]
        if val != -1:
            seen_values.add(val)
        else:
            empty_positions.append(i)

    # Count remaining values not yet used (1 to n)
    remaining_values = [v for v in range(1, n + 1) if v not in seen_values]

    m = len(empty_positions)

    # Count how many positions have a conflict (position + 1 == some remaining value)
    c = 0
    for pos in empty_positions:
        if (pos + 1) in remaining_values:
            c += 1

    # Precompute factorials and inverse factorials for combinations
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    inv_fact = [1] * (m + 1)
    inv_fact[m] = pow(fact[m], MOD - 2, MOD)
    for i in range(m - 1, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD

    # Function to compute C(n, k) mod MOD
    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return (fact[n] * inv_fact[k] % MOD) * inv_fact[n - k] % MOD

    # Inclusion-exclusion: sum of (-1)^i * C(m, i) * (m - i)! for i in [0, c]
    result = 0
    for i in range(c + 1):
        term = comb(m, i) * fact[m - i] % MOD
        if i % 2 == 1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result)

