def get_prime_factors(n):
    """Return prime factorization as dict: {prime: exponent}"""
    factors = {}
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def get_lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return a * b // math.gcd(a, b)

