def partition_into_powers_of_2(n):
    memo = {}
    def f(x):
        if x in memo:
            return memo[x]
        if x == 0:
            return 1
        if x % 2 == 1:
            result = f(x - 1)
        else:
            result = f(x - 2) + f(x // 2)
        memo[x] = result
        return result
    return f(n)

