class DinicAlgorithm:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, capacity):
        forward = [v, capacity, 0]
        backward = [u, 0, 0]
        self.graph[u].append(forward)
        self.graph[v].append(backward)

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = [s]
        while queue:
            v = queue.pop(0)
            for to, cap, flow in self.graph[v]:
                if cap - flow > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    queue.append(to)
        return self.level[t] >= 0

    def dfs(self, v, t, pushed, ptr):
        if pushed == 0 or v == t:
            return pushed
        for i in range(ptr[v], len(self.graph[v])):
            ptr[v] = i
            to, cap, flow = self.graph[v][i]
            if self.level[v] + 1 != self.level[to] or cap - flow == 0:
                continue
            tr = self.dfs(to, t, min(pushed, cap - flow), ptr)
            if tr == 0:
                continue
            self.graph[v][i][2] += tr
            self.graph[to][len(self.graph[to]) - 1][2] -= tr
            return tr
        return 0

    def max_flow(self, s, t, k):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, k, ptr)
                if pushed == 0:
                    break
                flow += pushed
                k -= pushed
                if k == 0:
                    return flow
        return flow

