import sys

def solution(input_str):
    a, h, w = map(int, input_str.split())

    # Basic constraints - need at least one photo fitting dimension-wise
    if h < a or w < a:
        return "-1\n"

    A = h + a
    B = w + a
    C = w - h

    # Calculate lower bound for r such that c >= 1
    # From: c = (w - h + (w+a)*r) / (h+a) >= 1
    # This gives: r >= (2h + a - w) / (w + a)
    numerator_L = 2*h + a - w
    if numerator_L < 0:
        L = 1
    else:
        # Ceiling division: ceil(numerator_L / B)
        L = (numerator_L + B - 1) // B
        if L < 1:
            L = 1

    L = max(1, L)
    max_r = h // a

    if L > max_r:
        return "-1\n"

    min_x = float('inf')
    possible = False

    # Iterate through all valid r values
    for r in range(L, max_r + 1):
        numerator = C + B * r
        if numerator % A == 0:
            c = numerator // A
            if c >= 1:
                x = (h - r * a) / (r + 1)
                if x < min_x:
                    min_x = x
                    possible = True

    if not possible:
        return "-1\n"
    else:
        return f"{min_x:.10f}\n"

