def get_primes(x):
    """Extract all prime factors of x (for x >= 2)."""
    primes = set()
    d = 2
    temp = x
    while d * d <= temp:
        if temp % d == 0:
            primes.add(d)
            while temp % d == 0:
                temp //= d
        d += 1 if d == 2 else 2  # Skip even numbers after 2
    if temp > 1:
        primes.add(temp)
    return primes


def solve_for_prime(arr, prime, n, a, b):
    """Compute minimum cost for a specific prime using no removal or optimal segment removal."""
    # Cost for each element: 0 if divisible, b if ±1 is divisible, inf otherwise
    costs = []
    for x in arr:
        if x % prime == 0:
            costs.append(0)
        elif (x - 1) % prime == 0 or (x + 1) % prime == 0:
            costs.append(b)
        else:
            costs.append(float('inf'))

    if any(c == float('inf') for c in costs):
        return float('inf')

    total_cost = sum(costs)
    min_cost = total_cost

    # Prefix sums for segment calculations
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + costs[i]

    # Strategy 1: Remove first segment of length k (0 <= k < n)
    for k in range(n):
        removal_cost = k * a
        keep_cost = total_cost - prefix[k]
        if k < n:
            min_cost = min(min_cost, keep_cost + removal_cost)

    # Strategy 2: Remove last segment of length k (0 <= k < n)
    for k in range(n):
        removal_cost = k * a
        keep_cost = prefix[n - k]
        if n - k >= 0:
            min_cost = min(min_cost, keep_cost + removal_cost)

    # Strategy 3: Remove middle segment using Kadane's approach
    # For optimal savings, we want to maximize sum(costs[l:r+1]) - (r-l+1)*a
    current = 0
    max_savings = 0

    for i in range(n):
        val = costs[i] - a
        current = max(0, current + val)
        max_savings = max(max_savings, current)

    if max_savings > 0:
        min_cost = min(min_cost, total_cost - max_savings)

    return min_cost


