    if n == 0 or len(strings) != n:
        return 'NO\n'

    # Valid input validation: non-empty strings
    for s in strings:
        if not s:
            return 'NO\n'

    # Build transition graph
    trans = {}
    all_c = set()

    for s in strings:
        for c in s:
            all_c.add(c)
        for i in range(len(s)-1):
            if s[i] in trans and trans[s[i]] != s[i+1]:
                return 'NO\n'
            trans[s[i]] = s[i+1]

    # Find starting chars (no incoming transitions)
    targets = set(trans.values())
    starts = sorted([c for c in all_c if c not in targets])

    if not starts:
        return 'NO\n'

    # Build path from lexicographically smallest start
    res = starts[0]
    curr = starts[0]
    while curr in trans:
        curr = trans[curr]
        res += curr

    # Verify all strings are present
    for s in strings:
        found = False
        for i in range(len(res) - len(s) + 1):
            if res[i:i+len(s)] == s:
                found = True
                break
        if not found:
            return 'NO\n'

    return res + '\n'

def solution(raw_input):
    lines = raw_input.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    queries = []
    for i in range(1, q + 1):
        if i < len(lines) and lines[i].strip():
            queries.append(int(lines[i].strip()))

    results = []

    def digit_count_upto(n):
        """Count total digits in numbers 1 to n"""
        if n <= 0:
            return 0
        total = 0
        d = 1
        start = 1
        while start <= n:
            end = min(n, 10**d - 1)
            total += (end - start + 1) * d
            start *= 10
            d += 1
        return total

    def cumulative_block_length(m):
        """Total length of all blocks from 1 to m"""
        total = 0
        for i in range(1, m + 1):
            total += digit_count_upto(i)
        return total

    for k in queries:
        # Binary search to find which block m contains position k
        low, high = 1, 1000000000
        block_m = high

        while low <= high:
            mid = (low + high) // 2
            # Calculate cumulative length up to block mid
            cum_len_m = digit_count_upto(mid)
            cum_len_before = 0
            if mid > 1:
                cum_len_before = digit_count_upto(mid - 1)

            if cum_len_m < k:
                low = mid + 1
            else:
                block_m = mid
                high = mid - 1

        # Calculate exact position within block m
        cum_len_before_m = cumulative_block_length(block_m - 1) if block_m > 1 else 0
        pos_in_block = k - cum_len_before_m

        # Find which number in the sequence 1, 2, ..., block_m contains the digit
        low2, high2 = 1, block_m
        num = high2

        while low2 <= high2:
            mid2 = (low2 + high2) // 2
            if digit_count_upto(mid2) >= pos_in_block:
                num = mid2
                high2 = mid2 - 1
            else:
                low2 = mid2 + 1

        # Calculate which digit within the number
        if num > 0:
            digits_before = digit_count_upto(num - 1)
        else:
            digits_before = 0
        digit_pos = pos_in_block - digits_before
        s = str(num)
        results.append(s[digit_pos - 1])

    return '\n'.join(results)

def dp_solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    if n < 3:
        return "0\n"

    vertices = []
    for i in range(n):
        parts = lines[1 + i].split()
        vertices.append((int(parts[0]), int(parts[1])))

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, q, r):
        return min(q[0], r[0]) <= p[0] <= max(q[0], r[0]) and \
               min(q[1], r[1]) <= p[1] <= max(q[1], r[1])

    def segments_do_intersect(p1, q1, p2, q2):
        d1 = cross_product(p2, q2, p1)
        d2 = cross_product(p2, q2, q1)
        d3 = cross_product(p1, q1, p2)
        d4 = cross_product(p1, q1, q2)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True

        return False

    def is_diagonal_valid(i, j):
        # Adjacent vertices form polygon edges, always valid
        if abs(i - j) == 1:
            return True
        # Handle the wraparound edge (0, n-1)
        if i == 0 and j == n - 1 or i == n - 1 and j == 0:
            return True

        # Check if diagonal (i, j) intersects any polygon edge
        # Skip edges that share endpoints with the diagonal
        for a in range(n):
            b = (a + 1) % n
            if a == i or a == j or b == i or b == j:
                continue
            if segments_do_intersect(vertices[i], vertices[j], vertices[a], vertices[b]):
                return False

        return True

    # Precompute valid diagonal matrix
    valid = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if is_diagonal_valid(i, j):
                valid[i][j] = valid[j][i] = True

    # dp[i][j] = number of valid triangulations of polygon chain from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: adjacent vertices form a valid edge
    for i in range(n):
        if valid[i][i + 1]:
            dp[i][i + 1] = 1

    # Fill DP for increasing intervals
    for length in range(2, n):
        for i in range(n - length + 1):
            j = i + length
            if not valid[i][j]:
                continue
            for k in range(i + 1, j):
                # Triangle (i, k, j) is valid if both diagonals are valid
                # Note: (i,j) is the diagonal we're using to split
                if valid[i][k] and valid[k][j]:
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    result = dp[0][n - 1] if valid[0][n - 1] else 0
    return str(result) + '\n'

