    MOD = 10**9 + 7

    # Precomputation might be needed for performance
    # But first let's verify the logic

    # We keep applying operations until 1 element remains
    prev_row = a
    prev_last_op_char = None  # Tracks the last operation's sign

    while len(prev_row) > 1:
        curr_row = []
        n_elements = len(prev_row)

        if prev_last_op_char is None:
            # First row, always start with +
            start_with = True
        else:
            # Next row starts with opposite sign
            start_with = (prev_last_op_char != '+')

        # Apply operations
        for i in range(n_elements - 1):
            if i == 0:
                # Use the starting sign for first op of this row
                op = '+' if start_with else '-'
            else:
                # Alternate sign within this row (starting from what first op used)
                if start_with:
                    op = '+' if i % 2 == 0 else '-'
                else:
                    op = '-' if i % 2 == 0 else '+'

            num1 = prev_row[i]
            num2 = prev_row[i+1]

            if op == '+':
                curr_row.append((num1 + num2) % MOD)
            else:
                curr_row.append((num1 - num2) % MOD)

        # Determine the last operation of this row for the next iteration
        if len(curr_row) > 0:
            op_type = '+' if (n_elements - 1) % 2 == 0 else '-'
            prev_last_op_char = op_type

        prev_row = curr_row

    return str(prev_row[0] % MOD)

