def solution(input_str):
    """
    Interactive problem solution - finds path from (1,1) to finish 'F'
    avoiding dangerous cells '*', handling possible direction swaps.
    """
    lines = input_str.strip().split('\n')

    # Parse initial line (may have n, m + swapLR, swapUD)
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    # Check if swap info is present (first line contains 4 values)
    if len(parts) == 4:
        swapLR = int(parts[2])
        swapUD = int(parts[3])
    else:
        swapLR, swapUD = 0, 0

    # Build grid
    grid = [list(line) for line in lines[1:1+n]]

    # Find start position and finish position
    start_r, start_c = 0, 0  # 0-indexed
    finish_r, finish_c = -1, -1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                finish_r, finish_c = i, j

    # Define actual direction mappings based on swaps
    # Standard: L=(-1,0), R=(0,1), U=(0,-1), D=(1,0) in (row, col)
    # Wait - actually let's determine the correct system by testing

    # Standard directional deltas (row, col)
    # U moves up (decrease row), D moves down (increase row)
    # L moves left (decrease col), R moves right (increase col)
    if swapLR:
        dir_map = {
            'U': (0, -1),  # Actually this doesn't swap
            'D': (0, 1),
        }
    else:
        dir_map = {
            'U': (-1, 0),
            'D': (1, 0),
        }

    # Correct mapping based on swaps
    if swapUD:
        u_dir, d_dir = (1, 0), (-1, 0)  # U becomes down, D becomes up
    else:
        u_dir, d_dir = (-1, 0), (1, 0)

    if swapLR:
        l_dir, r_dir = (0, 1), (0, -1)  # L becomes right, R becomes left
    else:
        l_dir, r_dir = (0, -1), (0, 1)

    all_moves = [('L', l_dir), ('R', r_dir), ('U', u_dir), ('D', d_dir)]

    # BFS to find shortest path
    dq = deque()
    dq.append((start_r, start_c, ""))
    visited = set([(start_r, start_c)])

    while dq:
        r, c, path = dq.popleft()

        if r == finish_r and c == finish_c:
            return path

        for move, (dr, dc) in all_moves:
            nr, nc = r + dr, c + dc
            name = move

            # Check bounds
            if 0 <= nr < n and 0 <= nc < m:
                # Check not dangerous
                name_cell = move
                if name_cell == 'L':
                    name_cell = 'grid'
                if name_cell == 'R':
                    name_cell = 'grid'
                if name_cell == 'U':
                    name_cell = 'grid'
                if name_cell == 'D':
                    name_cell = 'grid'
                # Actually check actual grid cell
                grid_cell = grid[nr][nc]
                if grid_cell == '*':
                    continue
                # Check not visited
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    dq.append((nr, nc, path + name + '\n'))

    # If BFS doesn't find a path, return empty or find any path (problem guarantees one exists)
    for move, (dr, dc) in all_moves:
        nr, nc = start_r + dr, start_c + dc
        if 0 <= nr < n and 0 <= nc < m:
            if grid[nr][nc] != '*':
                visited.add((nr, nc))
                dq.append((nr, nc, move + '\n'))

    while dq:
        r, c, path = dq.popleft()
        if r == finish_r and c == finish_c:
            return path
        for move, (dr, dc) in all_moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if grid[nr][nc] != '*' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    dq.append((nr, nc, path + move + '\n'))

    return ""

