class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [None] * (4 * self.n)
        self.arr = arr
        self._build(1, 0, self.n - 1)

    def _build(self, node, start, end):
        if start == end:
            self.tree[node] = [self.arr[start]]
        else:
            mid = (start + end) // 2
            self._build(2 * node, start, mid)
            self._build(2 * node + 1, mid + 1, end)
            self.tree[node] = sorted(self.tree[2 * node] + self.tree[2 * node + 1])

    def _merge(self, l_arr, r_arr):
        return sorted(l_arr + r_arr)

    def _query_count_less_equal(self, node, start, end, l, r, val):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            # Binary search for values <= val
            count = bisect_right(self.tree[node], val)
            return count
        mid = (start + end) // 2
        return (self._query_count_less_equal(2 * node, start, mid, l, r, val) + 
                self._query_count_less_equal(2 * node + 1, mid + 1, end, l, r, val))

    def update(self, idx, value):
        def update(node, start, end, idx):
            if start == end:
                self.tree[node] = [value]
            else:
                mid = (start + end) // 2
                if idx <= mid:
                    update(2 * node, start, mid, idx)
                else:
                    update(2 * node + 1, mid + 1, end, idx)
                self.tree[node] = self._merge(self.tree[2 * node], self.tree[2 * node + 1])

        update(1, 0, self.n - 1, idx)

def solution(data):
    lines = data.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            matrix.append(row)

        ops = lines[idx]
        idx += 1

        def get_inverse(row):
            inv = [0] * n
            for i, val in enumerate(row):
                inv[val - 1] = i + 1
            return inv

        for op in ops:
            if op == 'R':
                matrix = [row[-1:] + row[:-1] for row in matrix]
            elif op == 'L':
                matrix = [row[1:] + row[:1] for row in matrix]
            elif op == 'U':
                matrix = matrix[1:] + [matrix[0]]
            elif op == 'D':
                matrix = [matrix[-1]] + matrix[:-1]
            elif op == 'I':
                matrix = [get_inverse(row) for row in matrix]
            elif op == 'C':
                cols = list(zip(*matrix))
                inv_cols = [get_inverse(col) for col in cols]
                matrix = [list(el) for el in zip(*inv_cols)]

        results.append('\n'.join([' '.join(map(str, row)) for row in matrix]))

    return '\n\n'.join(results) + '\n'

def is_valid_set_score(sA, sB, is_five):
