def solution(s: str) -> str:
    """
    Solves the circuit re-soldering problem.

    The problem asks us to find the minimum number of re-soldering operations 
    needed so that all wires form a single connected component in the circuit graph.

    Two wires are connected if:
    - They share at least one contact point
    - OR there exists a sequence of wires where adjacent wires share contact points

    Each re-soldering operation changes one end of a wire to connect to a different contact point.
    """
    if not s or not s.strip():
        return ""

    lines = s.strip().split('\n')
    idx = 0

    # Skip any leading empty lines
    while idx < len(lines) and not lines[idx].strip():
        idx += 1

    if idx >= len(lines):
        return ""

    # Read number of test cases
    t = int(lines[idx].strip())
    idx += 1

    result_lines = []

    for _ in range(t):
        # Read number of wires
        while idx < len(lines) and not lines[idx].strip():
            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx].strip())
        idx += 1

        wires = []
        for i in range(n):
            while idx < len(lines) and not lines[idx].strip():
                idx += 1
            if idx >= len(lines):
                break
            parts = list(map(int, lines[idx].split()))
            wires.append((parts[0], parts[1]))
            idx += 1

        # Handle edge case: no wires
        if n == 0:
            result_lines.append("0")
            continue

        # Collect all contact points that appear in the input
        contact_points = set()
        for x in contact_points_update(wires):
            contact_points.update(x)

        # Build Union-Find data structure for contact points
        parent = {c: c for c in contact_points}

        def find(p):
            if parent[p] != p:
                parent[p] = find(parent[p])
            return parent[p]

        def union(p1, p2):
            root1, root2 = find(p1), find(p2)
            if root1 != root2:
                parent[root1] = root2
                return True
            return False

        # Unite contact points that are connected by wires
        for x, y in wires:
            union(x, y)

        # Count the number of connected components among contact points
        components = set()
        for c in contact_points:
            components.add(find(c))
        num_components = len(components)

        if num_components == 0 or num_components == 1:
            # All wires are already connected
            result_lines.append("0")
        else:
            # We need (num_components - 1) operations to connect all components
            ans = num_components - 1
            result_lines.append(str(ans))

            # Find component representatives
            reps = sorted(list(components))
            target_comp = reps[0]

            # Build mapping of wire -> (contact1_component, contact2_component)
            wire_info = []
            for w_idx, (x, y) in enumerate(wires):
                c1 = find(x)
                c2 = find(y)
                wire_info.append((w_idx, x, y, c1, c2))

            # Connect all components to target component
            modified = set()
            for w_idx, x, y, c1, c2 in wire_info:
                if w_idx in modified:
                    continue

                if c1 != target_comp and c2 != target_comp:
                    # Wire is in a component that's not the target
                    # Modify one endpoint to connect to target_comp
                    # Check if target_comp already appears somewhere as a valid contact
                    # Pick a contact point from the target component
                    if c1 != c2 or c1 == target_comp or c2 == target_comp:
                        # We can modify
                        if c1 == target_comp:
                            # Change y to also be in target_comp (reuse same contact)
                            # Pick any contact from target component
                            target_contacts = [c for c in contact_points if find(c) == target_comp]
                            if target_contacts:
                                new_val = target_contacts[0]
                                if target_contacts[0] != y:  # Ensure distinct endpoints
                                    result_lines.append(f"{w_idx + 1} {y} {new_val}")
                                    wire_info[w_idx] = (w_idx, x, new_val, c1, c2)
                                elif target_contacts:
                                    if x not in target_contacts:
                                        idx2 = target_contacts.index(x)
                                        if idx2 < len(target_contacts) - 1:
                                            idx3 = (idx2 + 1) % len(target_contacts)
                                            new_val = target_contacts[idx3]
                                        else:
                                            new_val = target_contacts[(idx2+1)]
                                    result_lines.append(f"{w_idx + 1} {y} {new_val}")
                                else:
