                            modified.add(w_idx)
                            found = True
                            break
                    if not found:
                        if y != target_contacts[(contact_idx + 1) % len(target_contacts)]:
                            result_lines.append(f"{w_idx + 1} {y} {target_contacts[(contact_idx + 1) % len(target_contacts)]}")
