    if not lines:
        return ""

    idx = 0

    while idx < len(lines) and not lines[idx].strip():
        idx += 1

    if idx >= len(lines):
        return ""

    t = int(lines[idx].strip())
    idx += 1

    result_lines = []

    for _ in range(t):
        while idx < len(lines) and not lines[idx].strip():
            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx].strip())
        idx += 1

        wires = []
        for i in range(n):
            while idx < len(lines) and not lines[idx].strip():
                idx += 1

            if idx >= len(lines):
                break

            parts = list(map(int, lines[idx].split()))
            wires.append((parts[0], parts[1]))
            idx += 1

        if n == 0:
            result_lines.append("0")
            continue

        # Collect all contact points
        contact_points = set()
        for x, y in wires:
            contact_points.add(x)
            contact_points.add(y)

        # Union-Find
        parent = {c: c for c in contact_points}

        def find(p):
            if parent[p] != p:
                parent[p] = find(parent[p])
            return parent[p]

        def union(p1, p2):
            root1, root2 = find(p1), find(p2)
            if root1 != root2:
                parent[root1] = root2
                return True
            return False

        for x, y in wires:
            union(x, y)

        # Count components
        components = set(find(c) for c in contact_points)
        num_components = len(components)

        if num_components <= 1:
            result_lines.append("0")
        else:
            ops = num_components - 1
            result_lines.append(str(ops))

            # Build component representatives
            rep_candidates = []
            for x, y in wires:
                c1, c2 = find(x), find(y)
                if c1 != c2:
                    rep_candidates.append((c1, c2))
                else:
                    rep_candidates.append((c1, c1))

            # Sort by component
            target_comp = sorted(components)[0]

            # Collect all possibilities
            connections = []

            for w_idx, (x, y) in enumerate(wires):
                c1, c2 = find(x), find(y)
                details = (w_idx + 1, y, target_comp)
                connections.append(details)

            # Output connections
            for conn in connections[:ops]:
                wi, a, b = conn
                result_lines.append(f"{wi} {a} {b}")

    return '\n'.join(result_lines)


