import sys

sys.setrecursionlimit(20000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, h, m = map(int, lines[0].split())
    restrictions = []
    for i in range(m):
        if i + 1 < len(lines):
            l, r, x, c = map(int, lines[i + 1].split())
            restrictions.append((l, r, x, c))

    if m == 0:
        return str(sum(a * a for a in range(h + 1)))

    memo = {}

    def solve(i, max_heights):
        if i == n:
            total_fine = 0
            for rid in range(m):
                l, r, x, c = restrictions[rid]
                if l <= r:
                    req_idx = -1
                    for j in range(l, min(r, i - 1) + 1):
                        if j >= 0 and j < i:
                            idx = j  # Since positions are 0-indexed internally
                            max_heights[rid] = max(max_heights[rid], height[idx])

            for rid in range(m):
                l, r, x, c = restrictions[rid]
                max_h = max_heights[rid]
                if l <= i - 1 and r >= i - 1 - 1:
                    if max_h > x:
                        total_fine += c

            return -total_fine

        key = (i, *max_heights)
        if key in memo:
            return memo[key]

        best = float('-inf')

        for height_i in range(h + 1):
            max_heights_new = list(max_heights)
            gain = height_i * height_i

            for rid in range(m):
                l, r, x, c = restrictions[rid]
                if l <= i <= r:
                    max_heights_new[rid] = max(max_heights[rid], height_i)
                    if height_i > x:
                        pass  # Fine will be calculated at end

            # Recurse
            result = solve(i + 1, max_heights_new)
            best = max(best, gain + result)

        memo[key] = best
        return best

    def solve_dp(i, max_heights):
        if i == n:
            total_fine = 0
            for rid in range(m):
                l, r, x, c = restrictions[rid]
                max_h = 0
                for j in range(l - 1, min(r, i - 1) + 1):  # 0-indexed positions
                    if j == i - 1:
                        max_h = max_heights[rid]
                    elif j > i - 1 and j < n:
                        # Would need additional state, but assume it's handled
                        pass
                if max_h > x:
                    total_fine += c
            return -total_fine

        held = {}

        def solve_complete(i, max_heights):
            if (i, tuple(max_heights)) in held:
                return held[(i, tuple(max_heights))]

            final_fine = 0
            for rid in range(m):
                l, r, x, c = restrictions[rid]
                l_idx = l - 1
                r_idx = r - 1
                max_h = max_heights[rid]
                if max_h > x:
                    final_fine += c

            total_gain = 0
            for height in total_height:
                total_gain += height * height

            total_fine += final_fine
            result = total_gain - total_fine

            held[(i, tuple(max_heights))] = result

            return result

    # Simpler approach: try all assignments (too slow)
    # Better: use memoized DP where state is (position, max_heights for active restrictions)

    memo_dp = {}

    def dp_helper(i, max_heights):
        if i == n:
            fine = 0
            for rid in range(m):
                l, r, x, c = restrictions[rid]
                max_h = max_heights[rid]
                if max_h > x:
                    fine += c
            return -fine

        key = (i, *max_heights)
        if key in memo_dp:
            return memo_dp[key]

        result = float('-inf')

        for h_i in range(h + 1):
            new_max = list(max_heights)
            for rid in range(m):
                l, r, x, c = restrictions[rid]
                if l <= i + 1 <= r:
                    new_max[rid] = max(min(max_heights[rid] if rid < len(max_heights) else 0, 1000000), h_i)

            sub_result = dp_helper(i + 1, new_max)
            result = max(result, h_i * h_i + sub_result)

        memo_dp[key] = result
        return result

    # Initialize: pos 0, max_heights all 0 (but only for restrictions that start at or before 0)
    init_max = [0] * m
    for rid in range(m):
        l, r, x, c = restrictions[rid]
        init_max[rid] = 0

    return str(dp_helper(0, init_max))

def solution(s):
    n, m = map(int, s.strip().split())

    # Find all distinct negative roots
    # x = -b - sqrt(b^2 - c) or x = -b + sqrt(b^2 - c)
    # For x = -k (k > 0), we have c = k^2 - 2b*k

    roots = set()

